// Generated by AI (UnitTest MCP)
import { execFileSync, spawnSync } from "node:child_process";
import assert from "node:assert/strict";
import { existsSync, mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

import {
  MARKER_NAME,
  ownershipVerdict,
  refusalMessage,
} from "./worktree-owner.mjs";

test("a human running git directly is never locked out", () => {
  const verdict = ownershipVerdict({ recorded: "", session: "" });
  assert.deepEqual(verdict, { action: "skip", reason: "no session identity" });
});

test("the primary checkout is exempt, whatever is recorded", () => {
  const verdict = ownershipVerdict({
    recorded: "session:v1:someone",
    session: "session:v1:me",
    linked: false,
  });
  assert.deepEqual(verdict, { action: "skip", reason: "primary checkout" });
});

test("a deliberate adopt always records, even over an existing owner", () => {
  const verdict = ownershipVerdict({
    recorded: "session:v1:someone",
    session: "session:v1:me",
    adopt: true,
  });
  assert.deepEqual(verdict, {
    action: "record",
    reason: "deliberate handover",
  });
});

test("an unclaimed linked worktree is claimed by the acting session", () => {
  const verdict = ownershipVerdict({
    recorded: "",
    session: "session:v1:me",
  });
  assert.deepEqual(verdict, {
    action: "record",
    reason: "first commit claims the worktree",
  });
});

test("the recorded owner may keep acting in its own worktree", () => {
  const verdict = ownershipVerdict({
    recorded: "session:v1:me",
    session: "session:v1:me",
  });
  assert.deepEqual(verdict, { action: "allow", reason: "owner" });
});

test("a different session is refused, and the owner is named", () => {
  const verdict = ownershipVerdict({
    recorded: "session:v1:someone",
    session: "session:v1:me",
  });
  assert.deepEqual(verdict, {
    action: "refuse",
    reason: "owned by another agent",
    owner: "session:v1:someone",
  });
});

test("the refusal message names both the owner and the acting session", () => {
  const message = refusalMessage({
    owner: "session:v1:someone",
    session: "session:v1:me",
  });
  assert.match(message, /worktree owner : session:v1:someone/);
  assert.match(message, /you\s+: session:v1:me/);
  assert.match(message, /--adopt-worktree/);
});

// The regression this gap fix exists for: a linked worktree that has been
// created and declared, but never committed in, previously had no marker at
// all, so any guard consulting one read it as unclaimed. `git worktree add`
// fires `post-checkout` the moment it completes (confirmed empirically), and
// the hook now runs `worktree-owner.mjs --stage=post-checkout` there. This
// drives that exact script, through a real git worktree, with no commit ever
// made, and asserts the marker already names the creating session.
const run = (args, cwd) => execFileSync("git", args, { cwd, encoding: "utf8" });
const scriptPath = fileURLToPath(
  new URL("./worktree-owner.mjs", import.meta.url),
);

test("a freshly created worktree is owned before any commit is made", () => {
  const root = mkdtempSync(join(tmpdir(), "worktree-owner-"));
  const session = "session:v1:creating-agent";
  try {
    run(["init", "-q", "-b", "main"], root);
    run(["config", "user.email", "probe@example.com"], root);
    run(["config", "user.name", "Probe"], root);
    run(["commit", "-q", "--allow-empty", "-m", "init"], root);

    const wtPath = join(root, "wt1");
    run(["worktree", "add", "-b", "feature/x", wtPath, "main"], root);

    // Simulate the post-checkout hook firing right after creation, before the
    // creating session has committed anything in the new worktree.
    execFileSync("node", [scriptPath, "--stage=post-checkout"], {
      cwd: wtPath,
      encoding: "utf8",
      env: { ...process.env, LODESTAR_SESSION_ID: session },
    });

    const gitDir = run(["rev-parse", "--absolute-git-dir"], wtPath).trim();
    const markerPath = join(gitDir, MARKER_NAME);
    assert.equal(
      existsSync(markerPath),
      true,
      "the marker must exist before any commit",
    );
    assert.equal(readFileSync(markerPath, "utf8").trim(), session);

    // No commit exists in the new worktree yet — the marker predates it.
    const log = run(
      ["log", "--oneline", "feature/x", "--not", "main"],
      wtPath,
    ).trim();
    assert.equal(log, "", "the branch must carry no commits of its own yet");
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("post-checkout warns rather than refusing when another session owns it", () => {
  const root = mkdtempSync(join(tmpdir(), "worktree-owner-"));
  try {
    run(["init", "-q", "-b", "main"], root);
    run(["config", "user.email", "probe@example.com"], root);
    run(["config", "user.name", "Probe"], root);
    run(["commit", "-q", "--allow-empty", "-m", "init"], root);

    const wtPath = join(root, "wt1");
    run(["worktree", "add", "-b", "feature/x", wtPath, "main"], root);
    execFileSync("node", [scriptPath, "--stage=post-checkout"], {
      cwd: wtPath,
      encoding: "utf8",
      env: { ...process.env, LODESTAR_SESSION_ID: "session:v1:owner" },
    });

    // A different session's post-checkout must not throw or block: git has
    // already performed the checkout, so this can only ever warn.
    const result = spawnSync("node", [scriptPath, "--stage=post-checkout"], {
      cwd: wtPath,
      encoding: "utf8",
      env: { ...process.env, LODESTAR_SESSION_ID: "session:v1:intruder" },
    });
    assert.equal(result.status, 0, "post-checkout must never block a checkout");
    assert.match(
      result.stderr,
      /this worktree already belongs to another agent/,
    );
    assert.match(result.stderr, /session:v1:owner/);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});
